import{z as A,x as o,o as r,c as p,q as t,j as B,D as e,d as i,s as l,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"强平与缺口风险","description":"","frontmatter":{"title":"强平与缺口风险","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/liquidation-gap-risk.md","filePath":"quant/liquidation-gap-risk.md","lastUpdated":1791413859000}'),d={name:"quant/liquidation-gap-risk.md"};function u(m,a,h,c,f,q){const n=o("Mermaid");return r(),p("div",null,[a[2]||(a[2]=t('<h1 id="强平与缺口风险" tabindex="-1">强平与缺口风险 <a class="header-anchor" href="#强平与缺口风险" aria-label="Permalink to &quot;强平与缺口风险&quot;">​</a></h1><div class="epigraph"><p>维持保证金被击穿后，下一笔可成交价格不一定在维持线上；跳空缺口让强平发生在更差的价位，损失大于「刚好减到合规」的回测。</p><footer>—— 据 Brunnermeier and Pedersen, 2009；Harris, Trading and Exchanges 对强制平仓与市场中断的讨论整理</footer></div><p>上一课<a href="/quant/margin-maintenance">保证金与维持保证金</a>把维持线写成每日检查。若价格连续，似乎总能在线上减仓。真实路径有隔夜跳空、停牌复牌、涨跌停封死，下一可成交价可以远在线外。本课补缺口：强平不是沿着回测曲线滑到合规，而是在可成交集合上一次性砍仓。不重讲双线定义。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无缺口回测的隐含算法是：权益刚碰到维持线，立刻按该价格卖出（买入回补）到合规。缺口风险说：标记到市价的那一刻，可成交价已经跳过维持线，甚至跳过初始线与强平触发价。经纪商按规则市价平仓，成交在缺口后的第一笔可用流动性上。回测若用连续复权收盘价插值，会把这笔成交画在维持线上，系统性低估强平损失。</p><p><span class="marginnote">缺口可以拿楼梯来类比：连续价格假设你沿楼梯一级级往下走，每级都能落脚减仓；跳空则是楼梯中间缺了几级——维持线在楼上，落地时已经在楼下，触发价与成交价之间根本没有可成交的中间价位。</span></p><p>财务课的退市与停牌在这里变成资金事件：停牌期间保证金仍按最后价或按经纪商规则标记，复牌第一笔可能直接强平。</p><h3 id="强平不是自愿再平衡" tabindex="-1">强平不是自愿再平衡 <a class="header-anchor" href="#强平不是自愿再平衡" aria-label="Permalink to &quot;强平不是自愿再平衡&quot;">​</a></h3><p>再平衡可以选择等待；强平由规则触发，时间优先于信号。把强平日当成普通换手、用 VWAP 假设成交，是把强制减仓当成有耐心的执行。后课停牌涨跌停会细化可成交集合；本课先把「线外第一笔」写进损益。</p><p><span class="marginnote">期货与差价合约的自动减仓、穿仓保险基金是同一缺口的合约化版本。本课用股票保证金讲清楚机制，不把各交易所规则抄一遍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>状态机在检查维持线失败后进入强平：以<strong>下一可成交价格</strong>（开盘、复牌、涨跌停打开后的第一笔）按规则顺序平仓，直到满足恢复要求（有的规则要回到初始线，不只维持线）。缺口 = 触发标记价与实际成交价之差。回测禁止在触发日用收盘价「刚好」减仓。现金不足且无法追加时，允许权益为负（穿仓），不要用零截断假装有限责任——除非你的账户结构真的有限。</p><p><span class="marginnote">数字实例：持仓市值 200 万、权益 25 万，保证金比例 \\(12.5\\%\\)，跌破维持线 \\(15\\%\\) 触发强平。若只要求回到维持线，市值砍到约 167 万即可（减 33 万）；若要求恢复到初始线 \\(50\\%\\)，则要砍到 50 万（减 150 万）——恢复标准不同，同一天的强平量差 4 倍以上。</span></p><p>宇宙仍含退市：退市缺口本身可以是一次强平。</p>',14)),(r(),B(s,null,{default:e(()=>[l(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20MTN%5B%22%E7%BB%B4%E6%8C%81%E7%BA%BF%E5%87%BB%E7%A9%BF%22%5D%20--%3E%20GAP%5B%22%E4%B8%8B%E4%B8%80%E5%8F%AF%E6%88%90%E4%BA%A4%E4%BB%B7%22%5D%0A%20%20GAP%20--%3E%20LIQ%5B%22%E5%BC%BA%E5%88%B6%E5%B9%B3%E4%BB%93%22%5D%0A%20%20LIQ%20--%3E%20REST%5B%22%E6%81%A2%E5%A4%8D%E5%90%88%E8%A7%84%E6%88%96%E7%A9%BF%E4%BB%93%22%5D%0A%20%20CLOSE%5B%22%E7%94%A8%E6%94%B6%E7%9B%98%E5%88%9A%E5%A5%BD%E5%87%8F%E4%BB%93%22%5D%20--%3E%20BIAS%5B%22%E4%BD%8E%E4%BC%B0%E7%BC%BA%E5%8F%A3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"把强平单记成独立成交类型：时间戳是下一可成交，价格是当时可成交集合的边，数量由恢复规则决定。不要与信号再平衡合并成一笔净换手，否则你会以为自己在「主动高换手」。穿仓路径要留在样本里报告，删掉爆仓账户等于删掉资金约束最重要的左尾。期货自动减仓是同一逻辑的合约化，规则不同但禁止用标记价成交。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"缺口在波动聚集、流动性撤退时变大，与保证金上调同时出现，于是融资流动性螺旋被离散化：不是平滑去杠杆，而是一串跳空强平。多空因子的空头侧更易在跳空上涨时被强平回补，制造「空头挤压」路径，无约束回测里这些路径不存在。后课借券与回购会再加入能否借到券、抵押品被 haircut 的约束；没有券或没有抵押时，强平更早发生。",-1)),(r(),B(s,null,{default:e(()=>[l(n,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20Jump%5B%22%E9%9A%94%E5%A4%9C%E8%B7%B3%E7%A9%BA%20%2F%20%E5%A4%8D%E7%89%8C%20%2F%20%E6%B6%A8%E8%B7%8C%E5%81%9C%E6%89%93%E5%BC%80%22%5D%20--%3E%20Force%5B%22%E4%B8%80%E6%89%B9%E8%B4%A6%E6%88%B7%E8%A2%AB%E5%BC%BA%E5%B9%B3%22%5D%0A%20%20Force%20--%3E%20Vol%5B%22%E6%B3%A2%E5%8A%A8%E5%8A%A0%E5%89%A7%22%5D%0A%20%20Vol%20--%3E%20Tighten%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E4%B8%8A%E8%B0%83%2C%20%E6%B5%81%E5%8A%A8%E6%80%A7%E6%92%A4%E9%80%80%22%5D%0A%20%20Tighten%20--%3E%20Wider%5B%22%E7%BC%BA%E5%8F%A3%E6%9B%B4%E5%A4%A7%22%5D%0A%20%20Wider%20--%3E%20Force%0A%20%20Short%5B%22%E7%A9%BA%E5%A4%B4%E4%BE%A7%E8%B6%8A%E7%BA%BF%22%5D%20--%3E%20BuyBack%5B%22%E8%A2%AB%E8%BF%AB%E4%B9%B0%E5%85%A5%E5%9B%9E%E8%A1%A5%22%5D%0A%20%20BuyBack%20--%3E%20Squeeze%5B%22%E7%A9%BA%E5%A4%B4%E6%8C%A4%E5%8E%8B%E6%8E%A8%E9%AB%98%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20Squeeze%20--%3E%20Vol%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">事件窗口里把强平当成普通成交，会把制度损失记进「事件 alpha」。业绩公告跳空尤其如此，后课事件策略必须复用本课的成交规则。</span></p><p>触发后禁止用当日收盘「刚好减到维持线」。成交价取下一开盘、复牌价或涨跌停打开后的第一笔，数量按规则一次砍到恢复要求（有的券商要求回到初始线）。穿仓允许权益为负，除非账户有限责任。把强平交易单独记账，不要混进主动再平衡的换手统计，否则成本归因会把强制减仓当成你自愿高换手。事件日跳空是本课最常见的触发器。</p><p><span class="marginnote">空头挤压可以翻译成「被迫买单」：借券做空的人在被强平或被召回券时必须买入股票还券，这笔买盘把价格推得更高，又让更多空头越线——下跌强平螺旋在这里方向反过来，涨得越急、强制买盘越大。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写各经纪商强平顺序的法务条款，不估计最优减仓算法。下一课<a href="/quant/margin-securities-lending">融资融券机制</a>把多头融资与空头借券拆开。涨跌停作为可成交约束的系统处理见<a href="/quant/halt-limit-backtest">停牌与涨跌停对回测</a>。后课默认：维持线失败按下一可成交价强平；连续价上的「刚好合规」不是合法成交。</p><p>后课融券会在召回时制造同类强制交易，不必等到维持线。本课把「下一可成交价」写成强平成交的唯一定义。连续复权价上的光滑去杠杆，从本课起视为非法成交假设。事件跳空、复牌、退市都是缺口来源，单独记账。</p><p>后课默认维持线失败按下一可成交价强平；连续价上减到刚好合规，不再视为合法成交。</p><p>恢复要求若是回到初始线而非维持线，强平数量大于「刚好合规」。这条规则必须写进状态机，禁止用维持线缺口去近似一条更严的恢复规则，否则危机路径会被画得过轻。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>维持线给出触发，缺口给出真实成交价。</li><li>用收盘插值减到合规，会低估强平损失。</li><li>强平是规则时间，不是信号再平衡。</li><li>跳空、复牌、退市都是缺口的来源。</li><li>无约束危机满仓回测缺的就是这些路径。</li><li>出处：Brunnermeier and Pedersen (2009)；Harris, <em>Trading and Exchanges</em>。</li></ul>',10))])}const _=A(d,[["render",u]]);export{D as __pageData,_ as default};
